===== telegram_assistant.py (77) =====
"""Sends Telegram messages to AHome's assistant and keeps per-chat context.

Messages go to the n8n router first. If n8n is not running, the bot asks the
local core directly with the same policy, so the answer is still local.
"""

from __future__ import annotations

import logging
import os
from collections import deque
from typing import Deque, Dict, Literal

import httpx

logger = logging.getLogger("telegram_gateway_bot")

LOCAL_CORE_URL = os.getenv("LOCAL_CORE_URL", "http://127.0.0.1:8090")
LOCAL_CORE_TOKEN = os.getenv("LOCAL_CORE_TOKEN", "")
N8N_WEBHOOK_URL = os.getenv("N8N_ASSISTANT_WEBHOOK", "http://127.0.0.1:5678/webhook/ahome-telegram")

Mode = Literal["auto", "fast", "balanced", "deeper"]
HISTORY_TURNS = 2  # Keep only the immediate context to prevent stale memory pollution

UNAVAILABLE = "المساعد المحلي غير متاح الآن. لم يتم إرسال رسالتك إلى أي خدمة خارجية."

_history: Dict[str, Deque[dict]] = {}
_modes: Dict[str, Mode] = {}


def reset_chat(chat_id: str) -> None:
    _history.pop(chat_id, None)


def set_mode(chat_id: str, mode: Mode) -> None:
    _modes[chat_id] = mode


def get_mode(chat_id: str) -> Mode:
    return _modes.get(chat_id, "auto")


async def ask_assistant(chat_id: str, user_id: str, text: str) -> str:
    # Reset stale context if asked from scratch or single question
    if any(k in text for k in ["من الأول", "محادثة جديدة", "انسى القديم", "سؤال جديد"]):
        reset_chat(chat_id)

    history = _history.setdefault(chat_id, deque(maxlen=HISTORY_TURNS * 2))
    payload = {"text": text, "user_id": user_id, "mode": get_mode(chat_id), "history": list(history)}
    headers = {"X-AHome-Worker": LOCAL_CORE_TOKEN}

    reply = await _post(N8N_WEBHOOK_URL, payload, headers, via="n8n")
    if reply is None:
        reply = await _post(f"{LOCAL_CORE_URL}/v1/assistant/reply", payload, headers, via="local core")
    if reply is None:
        return UNAVAILABLE

    history.append({"role": "user", "content": text})
    history.append({"role": "assistant", "content": reply})
    return reply


async def _post(url: str, payload: dict, headers: dict, via: str) -> str | None:
    try:
        async with httpx.AsyncClient(timeout=210.0) as client:
            response = await client.post(url, json=payload, headers=headers)
        if response.status_code != 200:
            logger.warning("Assistant via %s returned HTTP %s", via, response.status_code)
            return None
        data = response.json()
        route = data.get("route", {})
        logger.info("Assistant via %s: intent=%s effort=%s", via, route.get("intent"), route.get("effort"))
        reply = data.get("reply")
        return reply if isinstance(reply, str) and reply.strip() else None
    except (httpx.HTTPError, ValueError) as error:
        logger.info("Assistant via %s unavailable: %s", via, type(error).__name__)
        return None
