"""Calls from the Telegram bot to the local core's /v1/bot/* routes.

The person comes from the verified pairing and is sent as X-AHome-Person; the core checks
it again (only ahmed or habiba) and, for paired chats, re-checks the chat too.
Nothing here logs titles, times or message text.
"""

from __future__ import annotations

import logging
import os
from dataclasses import dataclass, field
from typing import Any

import httpx

logger = logging.getLogger("telegram_gateway_bot")

DEFAULT_URL = "http://127.0.0.1:8090"


@dataclass
class Reply:
    """What the bot sends back: text plus optional inline buttons (rows of {text, callback_data})."""

    text: str = ""
    keyboard: list[list[dict[str, str]]] | None = None


@dataclass
class CoreResult:
    ok: bool
    status: int = 0
    data: dict[str, Any] = field(default_factory=dict)
    code: str = ""  # core error code, or "unreachable"


class CoreClient:
    def __init__(self, base_url: str | None = None, token: str | None = None, transport: httpx.AsyncBaseTransport | None = None) -> None:
        self.base_url = base_url or os.getenv("LOCAL_CORE_URL", DEFAULT_URL)
        self._token = token
        self.transport = transport

    @property
    def token(self) -> str:
        return self._token if self._token is not None else os.getenv("LOCAL_CORE_TOKEN", "")

    async def call(self, method: str, path: str, person: str, chat_id: str, *, verify_chat: bool = True,
                   json: dict | None = None, params: dict | None = None) -> CoreResult:
        if not self.token:
            return CoreResult(False, 0, code="no_token")
        headers = {"X-AHome-Worker": self.token, "X-AHome-Person": person}
        if verify_chat:
            headers["X-AHome-Chat"] = str(chat_id)
        try:
            async with httpx.AsyncClient(timeout=8.0, transport=self.transport) as client:
                response = await client.request(method, f"{self.base_url}/v1/bot{path}", headers=headers, json=json, params=params)
        except httpx.HTTPError as error:
            logger.warning("Core call failed: %s", type(error).__name__)
            return CoreResult(False, 0, code="unreachable")
        try:
            body = response.json()
        except ValueError:
            body = {}
        if response.status_code in (200, 201):
            return CoreResult(True, response.status_code, body if isinstance(body, dict) else {})
        detail = body.get("detail") if isinstance(body, dict) else None
        return CoreResult(False, response.status_code, code=detail if isinstance(detail, str) else "error")
