"""Answer a question from the person's own notes with the local chat model (T-017).

Only notes the caller may read are retrieved, the model runs on this PC, and the reply must cite note ids. When no
note matches, nothing is sent to the model at all and the answer says so. The wording rules are in domain/notes_answer.py.
"""
from __future__ import annotations

from typing import Any

import httpx

from core.config import settings
from data.notes_search import search
from data.smart_ai_router import GAME_MODE_FILE, smart_ai_router
from domain import game_mode
from domain.ai_profiles import LOCAL_PROFILES, clean_answer
from domain.notes_answer import (  # noqa: F401  (SYSTEM is read by tests through this module)
    NOTHING_FOUND, SYSTEM, TOP_NOTES, UNAVAILABLE, build_prompt, cited_ids, language, sources_of,
)


async def chat(system: str, prompt: str, effort: str = "balanced") -> str:
    """One call to the local chat model. Raises httpx.HTTPError when Ollama or the model is missing."""
    plan = game_mode.plan_for(effort, prompt, game_mode.read_state(GAME_MODE_FILE))
    if plan.downgraded:
        effort = plan.effort
    profile = LOCAL_PROFILES[effort]
    payload: dict[str, Any] = {
        "model": profile.model, "stream": False, "options": {"num_ctx": profile.context_window, "temperature": 0.2},
        "messages": [{"role": "system", "content": system}, {"role": "user", "content": prompt}],
    }
    if profile.model.startswith("qwen3"):
        payload["think"] = False
    reply = await smart_ai_router.client.post(f"{settings.OLLAMA_BASE_URL}/api/chat", json=payload, timeout=profile.timeout_seconds)
    reply.raise_for_status()
    return clean_answer(reply.json().get("message", {}).get("content", ""))


async def ask(user: str, question: str) -> dict[str, Any]:
    lang = language(question)
    hits, method = await search(user, question, TOP_NOTES)
    if not hits:
        return {"answer": NOTHING_FOUND[lang], "sources": [], "cited": [], "tier": "no_match", "search": method}
    sources = sources_of(hits)
    try:
        answer = await chat(SYSTEM, build_prompt(question, hits))
    except httpx.HTTPError:
        answer = ""
    if not answer:
        return {"answer": UNAVAILABLE[lang], "sources": sources, "cited": [], "tier": "unavailable", "search": method}
    cited = cited_ids(answer, hits)
    return {"answer": answer, "sources": sources, "cited": cited, "tier": "local_ollama", "search": method}

