"use client";

/**
 * AI relay through Realtime Database, so the assistant works from phones too.
 *
 *   site  -> ai_jobs/{jobId} { id, user, kind, mode, prompt, history, status: "queued", createdAt }
 *   laptop (infra-daemons/firebase_bridge.py) claims the job, asks the local core,
 *          writes { status: "done", reply } or { status: "failed", error }
 *   laptop -> ai_worker { heartbeat (server ms, every 30s), coreOk }
 *
 * Nothing here invents an answer: if the laptop is off the caller gets an AiJobError.
 */

import { useCallback, useEffect, useState } from "react";
import { get, onValue, push, ref, remove, set } from "firebase/database";
import { getSanctuaryAuth, getSanctuaryRtdb, isHabibaEmail } from "@/lib/firebaseClient";
import { isFinishedAnswer } from "@/lib/relayCore";
import { cleanReply } from "@/lib/aiReplyText";

export type AiViewer = "ahmed" | "habiba";
export type AiJobKind = "chat" | "journal" | "scan" | "image" | "video" | "relay";
export type AiMode = "auto" | "fast" | "balanced" | "deeper";
export interface AiHistoryItem {
  role: "user" | "assistant";
  content: string;
}
export interface AiJobInput {
  user: AiViewer;
  kind: AiJobKind;
  prompt: string;
  mode?: AiMode;
  history?: AiHistoryItem[];
  /** Relay jobs only (docs/RELAY.md): the action name and its arguments. */
  action?: string;
  args?: object;
}

export type AiJobErrorCode = "offline" | "timeout" | "failed" | "write";

export class AiJobError extends Error {
  readonly code: AiJobErrorCode;
  /** Machine reason written by the laptop bridge (unsupported, timeout, core_down, core_error, expired, restarted). */
  readonly reason?: string;
  readonly kind?: AiJobKind;
  constructor(code: AiJobErrorCode, message: string, reason?: string, kind?: AiJobKind) {
    super(message);
    this.name = "AiJobError";
    this.code = code;
    this.reason = reason;
    this.kind = kind;
  }
}

export const JOB_TIMEOUT_MS = 200_000;
export const HEARTBEAT_FRESH_MS = 90_000;
const MAX_PROMPT = 8000;
const MAX_HISTORY = 24;

/** Best guess of who is using the site when a component was not handed the viewer. */
export function viewerFromAuth(): AiViewer {
  try {
    return isHabibaEmail(getSanctuaryAuth().currentUser?.email) ? "habiba" : "ahmed";
  } catch {
    return "ahmed";
  }
}

export function isArabicText(text: string): boolean {
  let arabic = 0;
  let latin = 0;
  for (const ch of text) {
    if (ch >= "؀" && ch <= "ۿ") arabic += 1;
    else if ((ch >= "a" && ch <= "z") || (ch >= "A" && ch <= "Z")) latin += 1;
  }
  return arabic >= latin;
}

/** Remove reasoning tags and raw markdown tokens so replies read as plain text. See aiReplyText.ts. */
export function cleanAiReply(raw: string, options: { keepCode?: boolean } = {}): string {
  return cleanReply(raw, options);
}

export async function submitJob(input: AiJobInput): Promise<string> {
  try {
    const db = getSanctuaryRtdb();
    const jobRef = push(ref(db, "ai_jobs"));
    const id = jobRef.key;
    if (!id) throw new Error("no job id");
    const history = (input.history ?? [])
      .filter((item) => item.content.trim())
      .slice(-MAX_HISTORY)
      .map((item) => ({ role: item.role, content: item.content.slice(0, MAX_PROMPT) }));
    // The PC bridge trusts only the uid the database rules tie to the signed-in account.
    const uid = getSanctuaryAuth().currentUser?.uid;
    await set(jobRef, {
      id,
      user: input.user,
      ...(uid ? { uid } : {}),
      ...(input.action ? { action: input.action, args: input.args ?? {} } : {}),
      kind: input.kind,
      mode: input.mode ?? "auto",
      prompt: input.prompt.slice(0, MAX_PROMPT),
      ...(history.length ? { history } : {}),
      status: "queued",
      createdAt: Date.now(),
    });
    return id;
  } catch {
    throw new AiJobError("write", "Could not send the request.");
  }
}

