def ollama_opener(client: httpx.AsyncClient, base_url: str) -> Opener:
    """Opener that streams /api/chat and yields only the answer text (never hidden reasoning)."""
    async def open_stream(profile: LocalProfile, messages: List[Dict[str, str]]) -> AsyncIterator[str]:
        payload: Dict[str, Any] = {"model": profile.model, "messages": messages, "stream": True,
                                   "options": profile.options(), "keep_alive": profile.keep_alive}
        if profile.model.startswith("qwen3"):
            payload["think"] = profile.think
        timeout = httpx.Timeout(profile.timeout_seconds, connect=5.0)
        async with client.stream("POST", f"{base_url}/api/chat", json=payload, timeout=timeout) as resp:
            resp.raise_for_status()
            async for line in resp.aiter_lines():
                if not line:
                    continue
                chunk = json.loads(line)
                if chunk.get("error"):
                    raise httpx.HTTPError(str(chunk["error"])[:80])
                yield chunk.get("message", {}).get("content", "")
                if chunk.get("done"):
                    return
    return open_stream

def ollama_opener(client: httpx.AsyncClient, base_url: str) -> Opener:
