{"code": "const t0=Date.now();
const res = await fetch("http://127.0.0.1:11434/api/chat",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({model:"qwen3.5:9b",messages:[{role:"user",content:"Explain in two sentences why the sky is blue."}],stream:false,think:false,keep_alive:-1,options:{num_predict:120}})});
const b=await res.json();
console.log("speed:", JSON.stringify({ms:Date.now()-t0, eval:b.eval_count, eval_ms:Math.round((b.eval_duration||0)/1e6), tokps: b.eval_count? +(b.eval_count/((b.eval_duration||1)/1e9)).toFixed(1):null, content:(b.message?.content||"").slice(0,100)}));
const ps = await fetch("http://127.0.0.1:11434/api/ps").then(r=>r.json());
console.log("ps:", JSON.stringify(ps.models.map(m=>({ctx:m.context_length,size_mb:Math.round(m.size/1048576),vram_mb:Math.round(m.size_vram/1048576)}))));
", "description": "Measure generation speed at current offload"}

