{"code": "const t0=Date.now();
const res = await fetch("http://127.0.0.1:11434/api/chat",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({model:"qwen3.5:9b",messages:[{role:"user",content:"Say OK"}],stream:false,keep_alive:-1,options:{num_ctx:16384,num_predict:6}})});
const b=await res.json();
console.log("reload:", JSON.stringify({status:res.status, ms:Date.now()-t0, load_ms:Math.round((b.load_duration||0)/1e6), err:b.error}));
await new Promise(r=>setTimeout(r,1500));
const ps = await fetch("http://127.0.0.1:11434/api/ps").then(r=>r.json());
console.log("ps:", JSON.stringify(ps.models.map(m=>({ctx:m.context_length,size_mb:Math.round(m.size/1048576),vram_mb:Math.round(m.size_vram/1048576)}))));
const t1=Date.now();
const res2 = await fetch("http://127.0.0.1:11434/api/chat",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({model:"qwen3.5:9b",messages:[{role:"user",content:"Explain in two sentences why the sky is blue."}],stream:false,think:false,keep_alive:-1,options:{num_ctx:16384,num_predict:120}})});
const b2=await res2.json();
console.log("speed@16k:", JSON.stringify({ms:Date.now()-t1, eval:b2.eval_count, tokps: b2.eval_count? +(b2.eval_count/((b2.eval_duration||1)/1e9)).toFixed(1):null}));
", "description": "Reload at 16384 context and measure speed"}

