function run(cmd, timeout=150000){ return new Promise(r => cp.exec(cmd, { shell:"C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe", env: ENV, windowsHide: true, maxBuffer: 20*1024*1024, timeout }, (e,so,se)=>r({e:e?e.code:0, so, se}))); }
const script = `
$vbs = 'D:\\Projects\\AHome\\infra-daemons\\run-hidden.vbs'
$user = "$env:USERDOMAIN\\$env:USERNAME"

$settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable -MultipleInstances IgnoreNew -ExecutionTimeLimit (New-TimeSpan -Minutes 15)

# guard: at logon, then every 5 minutes
$actionGuard = New-ScheduledTaskAction -Execute 'C:\\WINDOWS\\System32\\wscript.exe' -Argument ('//B //Nologo "' + $vbs + '" powershell "D:\\Projects\\_SIR\\scripts\\ollama-guard.ps1" -Quiet') -WorkingDirectory 'D:\\Projects\\_SIR\\scripts'
$t1 = New-ScheduledTaskTrigger -AtLogOn
$t1.Delay = 'PT2M'
$t2 = New-ScheduledTaskTrigger -Once -At (Get-Date).AddMinutes(3) -RepetitionInterval (New-TimeSpan -Minutes 5) -RepetitionDuration (New-TimeSpan -Days 3650)
$guardPrincipal = New-ScheduledTaskPrincipal -UserId $user -LogonType Interactive -RunLevel Limited
Register-ScheduledTask -TaskName 'SIR_Ollama_Guard' -Action $actionGuard -Trigger @($t1,$t2) -Settings $settings -Principal $guardPrincipal -Description 'Keeps the local AI brain safe: unloads background models on low RAM, frees the GPU during games, keeps qwen3.5:9b resident.' -Force | Out-Null

# warm-up: at logon only
$actionWarm = New-ScheduledTaskAction -Execute 'C:\\WINDOWS\\System32\\wscript.exe' -Argument ('//B //Nologo "' + $vbs + '" powershell "D:\\Projects\\_SIR\\scripts\\ollama-warmup.ps1"') -WorkingDirectory 'D:\\Projects\\_SIR\\scripts'
$t3 = New-ScheduledTaskTrigger -AtLogOn
$t3.Delay = 'PT1M'
Register-ScheduledTask -TaskName 'SIR_Ollama_Warmup' -Action $actionWarm -Trigger $t3 -Settings $settings -Principal $guardPrincipal -Description 'Loads qwen3.5:9b at logon so the first AHome message is not a cold start.' -Force | Out-Null

Get-ScheduledTask -TaskName 'SIR_Ollama_Guard','SIR_Ollama_Warmup' | ForEach-Object { "$($_.TaskName) [$($_.State)] $($_.Actions.Arguments)" }
`;
const r = await run(script);
console.log(r.so + r.se);
", "description": "Register Ollama guard and warm-up scheduled tasks"}

