const p = "C:\\Users\\a7med\\.ollama\\config.json";
const raw = fs.readFileSync(p, "utf8");
const cfg = JSON.parse(raw);
fs.writeFileSync(p + ".bak-2026-11-13", raw);
for (const name of Object.keys(cfg.integrations || {})) {
  const it = cfg.integrations[name];
  if (Array.isArray(it.models)) it.models = it.models.map(m => (m === "qwen3:8b" ? "qwen3.5:9b" : m));
