if (cfg.last_model === "qwen3:8b") cfg.last_model = "qwen3.5:9b";
fs.writeFileSync(p, JSON.stringify(cfg, null, 2) + "\n");
console.log(fs.readFileSync(p,"utf8"));
", "description": "Fix stale qwen3:8b in ollama config.json"}

