const ENV = {...process.env, USERPROFILE:"C:\\Users\\a7med", APPDATA:"C:\\Users\\a7med\\AppData\\Roaming", LOCALAPPDATA:"C:\\Users\\a7med\\AppData\\Local", HOME:"C:\\Users\\a7med", SYSTEMROOT:"C:\\Windows", PATH:"C:\\Windows\\System32;C:\\Windows;C:\\Windows\\System32\\WindowsPowerShell\\v1.0"};
function run(cmd, timeout=180000){ return new Promise(r => cp.exec(cmd, { shell:"C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe", env: ENV, windowsHide: true, maxBuffer: 20*1024*1024, timeout }, (e,so,se)=>r({e:e?e.code:0, so, se}))); }
const r = await run(`
Stop-ScheduledTask -TaskName 'AHome-Services' -ErrorAction SilentlyContinue
Start-Sleep -Seconds 4
Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -match 'uvicorn main:app|telegram_gateway_bot|firebase_bridge|web_push_delivery|ahome-service-supervisor' } | ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }
