const envTxt = fs.readFileSync("D:\\Projects\\AHome\\apps\\local-core\\.worker.env","utf8");
const token = (envTxt.match(/LOCAL_CORE_TOKEN=(.+)/)||[])[1].trim().replace(/^["']|["']$/g,"");
console.log("token present:", !!token, "len:", token.length);
async function reply(text, mode) {
  const t0 = Date.now();
  const res = await fetch("http://127.0.0.1:8090/v1/assistant/reply", {method:"POST", headers:{"content-type":"application/json","X-AHome-Worker":token}, body: JSON.stringify({text, user_id:"ahmed", mode, history:[]})});
  const body = await res.json();
  return {mode, status: res.status, ms: Date.now()-t0, tier: body.tier, route: body.route, reply: (body.reply||"").slice(0,300)};
}
const r1 = await reply("إيه أسرع طريقة أذاكر بيها تشريح؟", "balanced");
console.log(JSON.stringify(r1, null, 1));
const ps = await fetch("http://127.0.0.1:11434/api/ps").then(r=>r.json());
console.log("ps during:", JSON.stringify(ps.models.map(m=>({name:m.name,ctx:m.context_length,vram_mb:Math.round(m.size_vram/1048576),expires:m.expires_at}))));
", "description": "Call local-core reply API with a real Arabic question"}

