{"code": "const fs = await import("node:fs");
const probe = `import asyncio, json, traceback
import httpx
from core.config import settings
from data.ollama_stream import Limits, ask as stream_ask, loaded_checker, ollama_opener, attempt_once
from domain.ai_profiles import LOCAL_PROFILES, build_messages

profile = LOCAL_PROFILES["fast"]
msgs = build_messages("إيه أسرع طريقة أذاكر بيها تشريح؟", [], "ahmed")
client = httpx.AsyncClient(timeout=25.0)
opener = ollama_opener(client, settings.OLLAMA_BASE_URL)
checker = loaded_checker(client, settings.OLLAMA_BASE_URL)

async def main():
    print("is_warm:", await checker(profile.model))
    print("payload:", json.dumps(profile.payload(msgs, True))[:300])
    # raw stream probe
    try:
        async for line in (await client.stream("POST", settings.OLLAMA_BASE_URL + "/api/chat", json=profile.payload(msgs, True)).__aenter__()).aiter_lines():
            print("line:", line[:200])
            break
    except Exception as e:
        print("raw stream error:", type(e).__name__, str(e)[:300])
    outcome = await stream_ask(opener, [profile], msgs, checker, Limits(first_token_warm=20.0, first_token_cold=60.0, inactivity=25.0, total_cap=profile.timeout_seconds))
    print("text:", (outcome.text or "")[:200])
    for a in outcome.attempts:
        print("attempt:", a.model, a.reason, round(a.total_s,1), a.first_token_s, repr(a.text[:80]))

asyncio.run(main())
`;
fs.writeFileSync("D:\\Projects\\AHome\\apps\\local-core\\scripts\\_probe_router.py", probe);
const cp = await import("node:child_process");
const ENV = {...process.env, USERPROFILE:"C:\\Users\\a7med", APPDATA:"C:\\Users\\a7med\\AppData\\Roaming", LOCALAPPDATA:"C:\\Users\\a7med\\AppData\\Local", HOME:"C:\\Users\\a7med", SYSTEMROOT:"C:\\Windows", PATH:"C:\\Windows\\System32;C:\\Windows;D:\\Projects\\AHome\\apps\\local-core\\.venv\\Scripts", TEMP:"C:\\Users\\a7med\\AppData\\Local\\Temp"};
function spawn(exe, args, cwd, timeout=200000){ return new Promise(res=>{ const p = cp.spawn(exe, args, {env:ENV, cwd, windowsHide:true}); let o=""; p.stdout.on("data",d=>o+=d); p.stderr.on("data",d=>o+=d); const t=setTimeout(()=>{p.kill(); res({c:"timeout",o})}, timeout); p.on("close",c=>{clearTimeout(t); res({c,o})}); }); }
const r = await spawn(ENV.PATH.split(";")[2]+"\\python.exe", ["scripts\\_probe_router.py"], "D:\\Projects\\AHome\\apps\\local-core");
console.log("exit", r.c);
console.log(r.o.slice(-4000));
", "description": "Probe the streaming router path in python"}

